// ---------- Bloque 1: leer datos ----------
const { config: c, entrada } = $input.first().json;
const body = entrada.body || {};
const evento = body.evento;
const a = body.datos;

// ---------- Bloque 2: comprobar ----------
const esTexto = v => typeof v === 'string' && v.trim() !== '';
const esImporte = v => typeof v === 'number' && Number.isFinite(v) && v >= 0;
const esFecha = v => typeof v === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(v);

// Céntimos sin multiplicar decimales (mismo método que PF-04)
const cent = v => {
  if (!/^(0|[1-9]\d*)(\.\d{1,2})?$/.test(String(v))) throw new Error('Importe inválido');
  const [e, d = ''] = String(v).split('.');
  const n = Number(e) * 100 + Number(d.padEnd(2, '0'));
  if (!Number.isSafeInteger(n)) throw new Error('Importe fuera de rango');
  return n;
};

if (evento !== 'abono.registrado') throw new Error('Evento inesperado en PF-02');
if (!a || typeof a !== 'object' || Array.isArray(a)) throw new Error('Apartado ausente');
if (!Number.isInteger(a.id) || a.id < 1) throw new Error('Apartado sin id válido');
if (!esTexto(a.cliente) || !esTexto(a.producto)) {
  throw new Error('Faltan datos del cliente o del producto');
}
if (!esImporte(a.importe) || a.importe <= 0) throw new Error('Falta el importe del abono');
if (!esImporte(a.precio) || a.precio <= 0 || !esImporte(a.abonado) || !esImporte(a.pendiente)) {
  throw new Error('Faltan datos financieros del apartado');
}
if (!['activo', 'liquidado'].includes(a.estado)) throw new Error('Estado de apartado inesperado');
if (!esTexto(c.CORREO_MARISA) || !esTexto(c.CORREO_REMITENTE)) {
  throw new Error('Falta configuración de correo');
}

// La talla es opcional en la app: si falta, se indica sin fallar
const talla = esTexto(String(a.talla ?? '')) ? String(a.talla).trim() : 'no indicada';

const importeC = cent(a.importe);
const abonadoC = cent(a.abonado);
const pendienteC = cent(a.pendiente);

// Coherencia: liquidado solo con pendiente cero (no se corrige el estado)
const incoherente = (a.estado === 'liquidado') !== (pendienteC === 0);

// ---------- Bloque 3: decidir destino ----------
const email = typeof a.email === 'string' ? a.email.trim() : '';
const emailValido = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
const base = `abono.registrado:${a.id}:${abonadoC}:${importeC}`;

let destino, destinatario, clave, motivo;
if (incoherente) {
  destino = 'tienda';
  destinatario = c.CORREO_MARISA;
  clave = `${base}:tienda`;
  motivo = 'saldo_contradictorio';
} else if (emailValido) {
  destino = 'cliente';
  destinatario = email;
  clave = base;
  motivo = null;
} else {
  destino = 'tienda';
  destinatario = c.CORREO_MARISA;
  clave = `${base}:tienda`;
  motivo = email === '' ? 'email_ausente' : 'email_invalido';
}

// ---------- Bloque 4: escribir el mensaje ----------
const euros = n => n.toFixed(2).replace('.', ',') + ' €';

const resumen = [
  `Modelo: ${a.producto}`,
  `Talla: ${talla}`,
  `Importe de este abono: ${euros(a.importe)}`,
  `Total abonado: ${euros(a.abonado)}`,
  `Pendiente: ${euros(a.pendiente)}`
].join('\n');

const recogida = (a.estado === 'liquidado' && !incoherente)
  ? '\nEl apartado está pagado por completo: ya puedes pasar a recogerlo.\n'
  : '';

let asunto, texto;
if (destino === 'cliente') {
  asunto = `Paso Firme · Recibo de tu abono al apartado n.º ${a.id}`;
  texto = `Hola, ${a.cliente}:\n\n` +
    `Hemos recibido tu abono.\n\n` +
    `${resumen}\n${recogida}\n` +
    `Gracias por tu confianza.\nPaso Firme`;
} else {
  asunto = `Paso Firme · Abono del apartado n.º ${a.id} sin recibo al cliente`;
  texto = `Se ha registrado un abono en el apartado n.º ${a.id} de ${a.cliente}, ` +
    `pero no se ha enviado recibo al cliente (motivo: ${motivo}).\n\n` +
    `${resumen}\n\n` +
    `Teléfono registrado: ${a.telefono || 'no disponible'}.`;
}

// ---------- Bloque 5: devolver el documento ----------
return [{
  json: {
    clave,
    tipo: destino === 'cliente' ? 'recibo_abono' : 'aviso_abono_sin_recibo',
    documento: {
      apartado_id: a.id,
      destino,
      motivo,
      destinatario,
      remitente: c.CORREO_REMITENTE,
      asunto,
      texto
    }
  }
}];
